#include <zephyr/bluetooth/audio/micp.h>
#include <zephyr/bluetooth/audio/aics.h>
#include <zephyr/bluetooth/audio/bass.h>
#include <zephyr/bluetooth/audio/bap_lc3_preset.h>

#include "cap_initiator.h"
#include "cap_common.h"

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(bt_cap_initiator, CONFIG_BT_CAP_INITIATOR_LOG_LEVEL);

#define BT_DBG_ENABLED IS_ENABLED(CONFIG_BT_CAP_INITIATOR_DEBUG_LOG)
#define LOG_DBG(...) BT_DBG(__VA_ARGS__)
#define LOG_ERR(...) BT_ERR(__VA_ARGS__)
#define LOG_INF(...) BT_INFO(__VA_ARGS__)
#define LOG_WRN(...) BT_WARN(__VA_ARGS__)

#define CAP_INITIATOR_PROC_COUNT CONFIG_BT_CAP_INITIATOR_MAX_PROC_CNT
#define CAP_INITIATOR_STREAM_COUNT (CAP_INITIATOR_PROC_COUNT * \
				    CONFIG_BT_CAP_INITIATOR_MAX_STREAMS_PER_PROC)

struct bt_cap_initiator_stream {
	struct bt_bap_stream *bap_stream;
	struct bt_cap_initiator_proc *proc;
	struct bt_cap_initiator_stream_ops ops;
	void *user_data;
	bool active;
};

struct bt_cap_initiator_proc {
	struct bt_cap_initiator_proc_param param;
	struct bt_cap_initiator_stream streams[CONFIG_BT_CAP_INITIATOR_MAX_STREAMS_PER_PROC];
	struct bt_cap_initiator_proc_ops ops;
	void *user_data;
	enum bt_cap_initiator_proc_state state;
	uint8_t subproc_cnt;
	uint8_t subproc_done_cnt;
	uint8_t subproc_qos_configured_cnt;
	uint8_t subproc_enabled_cnt;
	uint8_t subproc_started_cnt;
	uint8_t subproc_metadata_updated_cnt;
	uint8_t subproc_released_cnt;
	uint8_t subproc_stopped_cnt;
	uint8_t subproc_disabled_cnt;
	uint8_t subproc_disconnected_cnt;
	uint8_t subproc_qos_released_cnt;
	uint8_t subproc_qos_configured_failed_cnt;
	uint8_t subproc_enabled_failed_cnt;
	uint8_t subproc_started_failed_cnt;
	uint8_t subproc_metadata_updated_failed_cnt;
	uint8_t subproc_released_failed_cnt;
	uint8_t subproc_stopped_failed_cnt;
	uint8_t subproc_disabled_failed_cnt;
	uint8_t subproc_disconnected_failed_cnt;
	uint8_t subproc_qos_released_failed_cnt;
	struct k_work_delayable timeout_work;
	struct k_work_delayable release_timeout_work;
	struct k_work_delayable stop_timeout_work;
	struct k_work_delayable disable_timeout_work;
	struct k_work_delayable release_qos_timeout_work;
	struct k_work_delayable disconnect_timeout_work;
	struct k_work_delayable qos_configured_timeout_work;
	struct k_work_delayable enabled_timeout_work;
	struct k_work_delayable started_timeout_work;
	struct k_work_delayable metadata_updated_timeout_work;
	struct k_work_delayable stopped_timeout_work;
	struct k_work_delayable disabled_timeout_work;
	struct k_work_delayable disconnected_timeout_work;
	struct k_work_delayable qos_released_timeout_work;
};

static struct bt_cap_initiator_proc cap_initiator_procs[CAP_INITIATOR_PROC_COUNT];

static K_MUTEX_DEFINE(active_proc_mutex);

static struct bt_cap_initiator_proc *cap_initiator_proc_get(void)
{
	for (size_t i = 0; i < ARRAY_SIZE(cap_initiator_procs); i++) {
		if (cap_initiator_procs[i].state == BT_CAP_INITIATOR_PROC_STATE_IDLE) {
			return &cap_initiator_procs[i];
		}
	}

	return NULL;
}

static struct bt_cap_initiator_proc *lookup_proc_by_param(
	const struct bt_cap_initiator_proc_param *param)
{
	for (size_t i = 0; i < ARRAY_SIZE(cap_initiator_procs); i++) {
		if (&cap_initiator_procs[i].param == param) {
			return &cap_initiator_procs[i];
		}
	}

	return NULL;
}

static struct bt_cap_initiator_proc *lookup_proc_by_stream(
	const struct bt_bap_stream *bap_stream)
{
	for (size_t i = 0; i < ARRAY_SIZE(cap_initiator_procs); i++) {
		for (size_t j = 0; j < ARRAY_SIZE(cap_initiator_procs[i].streams); j++) {
			if (cap_initiator_procs[i].streams[j].bap_stream == bap_stream) {
				return &cap_initiator_procs[i];
			}
		}
	}

	return NULL;
}

static struct bt_cap_initiator_stream *lookup_cap_stream(
	const struct bt_bap_stream *bap_stream)
{
	for (size_t i = 0; i < ARRAY_SIZE(cap_initiator_procs); i++) {
		for (size_t j = 0; j < ARRAY_SIZE(cap_initiator_procs[i].streams); j++) {
			if (cap_initiator_procs[i].streams[j].bap_stream == bap_stream) {
				return &cap_initiator_procs[i].streams[j];
			}
		}
	}

	return NULL;
}

static void cap_initiator_proc_timeout(struct k_work *work)
{
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct bt_cap_initiator_proc *proc = CONTAINER_OF(dwork,
								  struct bt_cap_initiator_proc,
								  timeout_work);

	LOG_ERR("Process timeout for proc %p", proc);

	(void)bt_cap_common_lock_proc();

	if (proc->ops.timeout != NULL) {
		proc->ops.timeout(proc, proc->user_data);
	}

	bt_cap_common_unlock_proc();
}

static void cap_initiator_release_timeout(struct k_work *work)
{
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct bt_cap_initiator_proc *proc = CONTAINER_OF(dwork,
								  struct bt_cap_initiator_proc,
								  release_timeout_work);

	LOG_ERR("Release timeout for proc %p", proc);

	(void)bt_cap_common_lock_proc();

	if (proc->ops.release_timeout != NULL) {
		proc->ops.release_timeout(proc, proc->user_data);
	}

	bt_cap_common_unlock_proc();
}

static void cap_initiator_stop_timeout(struct k_work *work)
{
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct bt_cap_initiator_proc *proc = CONTAINER_OF(dwork,
								  struct bt_cap_initiator_proc,
								  stop_timeout_work);

	LOG_ERR("Stop timeout for proc %p", proc);

	(void)bt_cap_common_lock_proc();

	if (proc->ops.stop_timeout != NULL) {
		proc->ops.stop_timeout(proc, proc->user_data);
	}

	bt_cap_common_unlock_proc();
}

